customCSS:
.t, .history { color: #4c566a; }
.join { color: #a3be8c; }
.part, .quit { color: #4c566a; }
.kick, .error { color: #bf616a; }
.notice { color: #ebcb8b; }
.action { color: #b48ead; }
.mode, .nick, .topic, .server { color: #8fbcbb; }
.highlight { color: #c0c8d8; background-color: #3b4252; border-left: 3px solid #b48ead; padding-left: 8px; }
.reply { color: #4c566a; border-left: 2px solid #5e81ac; padding-left: 6px; }
.oper { color: #242933; background-color: #ebcb8b; }
.reactions { color: #5e81ac; background-color: #191d24; }
.card { background-color: #191d24; border-color: #4c566a; }
.card-title { color: #5e81ac; }
.card-desc { color: #4c566a; }
.daychange { color: #4c566a; border-color: #191d24; }
